const show=()=>{const rate=+ingress.value,hot=+localHours.value,total=+remoteDays.value*24,rewind=+rewindHours.value,localTiB=rate*3600*hot*3/1048576,remoteTiB=rate*3600*total/1048576,retained=rewind<=total,tier=!retained?'EXPIRED':rewind<=hot?'LOCAL':'REMOTE';world.textContent='Ingress: '+rate+' MiB/s | replication factor: 3
Local hot capacity estimate: '+localTiB.toFixed(1)+' TiB
Remote retained-data estimate: '+remoteTiB.toFixed(1)+' TiB
Rewind '+rewind+'h: '+tier+'

'+(tier==='LOCAL'?'Expected hot-path read in this toy model.':tier==='REMOTE'?'Logically retained, but remote fetch cost and latency matter.':'Outside overall retention; tiering cannot recover expired data.')};[ingress,localHours,remoteDays,rewindHours].forEach(e=>e.oninput=show);show();
function drawMechanism(){const hot=Math.min(+localHours.value,+remoteDays.value*24),total=+remoteDays.value*24,r=+rewindHours.value,max=Math.max(168,total+24),pct=x=>100*x/max;const path=r>total?'EXPIRED: no retained segment':r<=hot?'LOCAL broker disk':'REMOTE segment fetch';visualField.innerHTML='<p>Age increases from left to right. Both boundaries use the same hours scale.</p><div class="agepin"><b style="left:'+pct(r)+'%">↓</b></div><div class="agebar" aria-label="Local '+hot+' hours; retained '+total+' hours"><span class="agehot" style="width:'+pct(hot)+'%"></span><span class="agecold" style="width:'+pct(total-hot)+'%"></span><span class="agegone" style="width:'+pct(max-total)+'%"></span></div><p class="legend">0 h → local through '+hot+' h → remote through '+total+' h → expired. Ruler end: '+max+' h.</p><p><strong>Consumer at '+r+' h → '+path+'</strong></p><p>Increasing overall retention moves the expiry boundary. Increasing local retention moves only the local/remote boundary. The visual clips the hot window to overall retention; real configuration must be valid.</p>';}
const syncMechanism=()=>{show();drawMechanism();};[ingress,localHours,remoteDays,rewindHours].forEach(e=>e.oninput=syncMechanism);drawMechanism();

const originals=[40,45,50,55,80,900];const pct=(a,p)=>a.slice().sort((x,y)=>x-y)[Math.ceil(p*a.length)-1];const show=()=>{const d=+hedgeDelay.value,b=+backupLatency.value,completed=originals.map(x=>Math.min(x,d+b)),hedges=originals.filter(x=>x>d).length,wins=originals.filter(x=>d+b<x).length;world.textContent='Original latencies: '+originals.join(', ')+' ms
Completed latencies: '+completed.join(', ')+' ms
Toy p95/max: '+pct(completed,.95)+' ms
Hedges sent: '+hedges+'/'+originals.length+' ('+Math.round(100*hedges/originals.length)+'% extra attempts)
Backups that win: '+wins+'

'+(hedges===0?'No tail protection at this threshold.':hedges===originals.length?'Every request duplicates: maximum protection, maximum modeled overhead.':'Only requests beyond the threshold duplicate.')};[hedgeDelay,backupLatency].forEach(e=>e.oninput=show);show();
function drawMechanism(){const d=+hedgeDelay.value,b=+backupLatency.value;visualField.innerHTML='<p>Shared ruler: 0–1000 ms. Upper bar: original. Lower bar: backup starts at '+d+' ms. White tick: result returned.</p>'+originals.map((x,i)=>{const sent=x>d,finish=Math.min(x,d+b);return '<div class="hedge-row"><div class="hedge-label">Read '+(i+1)+': '+finish+' ms · '+(!sent?'no backup':d+b<x?'backup wins':'original wins; backup adds work')+'</div><div class="hedge-track"><span class="hedge-original" style="width:'+x/10+'%"></span>'+(sent?'<span class="hedge-backup" style="left:'+d/10+'%;width:'+b/10+'%"></span>':'')+'<span class="hedge-finish" style="left:'+finish/10+'%"></span></div></div>'}).join('')+'<p>At the default 100 ms delay, five reads finish before a backup starts. The 900 ms straggler returns at 170 ms instead. Bars show scheduled response times, not guaranteed cancellation of work.</p>';}
const syncMechanism=()=>{show();drawMechanism();};[hedgeDelay,backupLatency].forEach(e=>e.oninput=syncMechanism);drawMechanism();

const show=()=>{const score=+irreversible.value*2 + +blast.value + +uncertainty.value + (rollback.checked?0:3),mode=score<=4?'TWO-WAY DOOR: named owner, guardrail, fast experiment':score<=8?'CONDITIONAL: staged evidence, explicit reviewers, rollback rehearsal':'ONE-WAY DOOR: senior accountable owner, deep review, migration and repair plan';world.textContent='Heuristic risk score: '+score+'
Suggested decision path: '+mode+'
Rollback claim: '+(rollback.checked?'tested across code, data, and contract':'incomplete or untested')+'

This score organizes questions; it does not authorize a production change.'};[irreversible,blast,uncertainty,rollback].forEach(e=>e.oninput=show);show();
function drawMechanism(){const i=+irreversible.value,b=+blast.value,u=+uncertainty.value,r=rollback.checked?0:3,s=i*2+b+u+r;visualField.innerHTML='<table><caption>Why this decision needs review</caption><thead><tr><th>Evidence question</th><th>Contribution</th></tr></thead><tbody><tr><td>Can the effect be undone?</td><td>'+i+' × 2 = '+i*2+'</td></tr><tr><td>How many are exposed?</td><td>'+b+'</td></tr><tr><td>What is still unknown?</td><td>'+u+'</td></tr><tr><td>Was full reversal rehearsed?</td><td>'+r+' ('+(rollback.checked?'yes':'no')+')</td></tr></tbody></table><div class="decision-path"><p>These inputs → '+s+' heuristic points → <strong>'+(s<=4?'bounded experiment':s<=8?'gather evidence in stages':'deep review before commitment')+'</strong></p><ol><li>Propose a smaller, reversible scope.</li><li>Test recovery of code, data, and consumer contracts.</li><li>'+(s<=4?'Name an owner and a stop rule, then learn from the experiment.':s<=8?'Resolve uncertainty and rehearse rollback before widening exposure.':'Require an accountable senior owner and a migration/repair plan.')+'</li></ol></div><p>Compare a dashboard sort change with deleting an external field: code rollback alone cannot repair consumers that already failed.</p>';}
const syncMechanism=()=>{show();drawMechanism();};[irreversible,blast,uncertainty,rollback].forEach(e=>e.oninput=syncMechanism);drawMechanism();

const tracePath=()=>{let steps=['Untrusted README influences model.'];if(fsIsolation.checked){steps.push('BLOCK: filesystem denies ~/.ssh read.');world.textContent=steps.join('
');return}steps.push('Sensitive file is readable.');if(networkIsolation.checked){steps.push('BLOCK: network denies attacker host.');world.textContent=steps.join('
');return}steps.push('Attacker host is reachable.');if(externalCredentials.checked)steps.push('Long-lived service credential is not present.');else steps.push('Ambient credential is exposed.');if(scopedProxy.checked)steps.push('Git side path is constrained to configured repo/branch.');else steps.push('Git credential path is broadly usable.');steps.push('EXFILTRATION PATH OPEN for readable file in this toy model.');world.textContent=steps.join('
')};trace.onclick=tracePath;[fsIsolation,networkIsolation,externalCredentials,scopedProxy].forEach(e=>e.oninput=tracePath);tracePath();
function drawMechanism(){const f=fsIsolation.checked,n=networkIsolation.checked;visualField.innerHTML='<ol class="gate-path"><li>1. README text asks the agent to upload a private file.</li><li class="'+(f?'stop':'')+'">2. Read private file: <strong>'+(f?'DENIED — path stops':'ALLOWED — bytes can enter agent context')+'</strong></li><li class="'+(f?'unreached':n?'stop':'')+'">3. Contact attacker host: <strong>'+(f?'NOT REACHED':n?'DENIED — upload stops':'ALLOWED — readable bytes can leave')+'</strong></li><li class="'+(f||n?'unreached':'stop')+'">4. Result: '+(f||n?'No exfiltration on this modeled path':'EXFILTRATION PATH OPEN')+'</li></ol><div class="authority-note"><strong>Separate authority paths</strong><p>Long-lived credential: '+(externalCredentials.checked?'kept outside sandbox':'available inside sandbox')+'.</p><p>Git proxy: '+(scopedProxy.checked?'only selected repository/branch':'broad repository authority')+'. These controls do not substitute for file and egress gates.</p></div>';}
const syncMechanism=()=>{tracePath();drawMechanism();};[fsIsolation,networkIsolation,externalCredentials,scopedProxy].forEach(e=>e.oninput=syncMechanism);trace.onclick=syncMechanism;drawMechanism();

const show=()=>{const n=10000,p=+prevalence.value/100,se=+sensitivity.value/100,sp=+specificity.value/100,tp=n*p*se,fn=n*p*(1-se),fp=n*(1-p)*(1-sp),tn=n*(1-p)*sp,ppv=100*tp/(tp+fp);world.textContent='Synthetic cohort: 10,000
True positives: '+tp.toFixed(0)+' | False negatives: '+fn.toFixed(0)+'
False positives: '+fp.toFixed(0)+' | True negatives: '+tn.toFixed(0)+'
Positive predictive value: '+ppv.toFixed(1)+'%

These are teaching inputs, not product performance or clinical guidance.'};[prevalence,sensitivity,specificity].forEach(e=>e.oninput=show);show();
function drawMechanism(){const p=+prevalence.value/100,se=+sensitivity.value/100,sp=+specificity.value/100,sick=10000*p,well=10000-sick,tp=sick*se,fp=well*(1-sp),positive=tp+fp;visualField.innerHTML='<p>10,000 synthetic people</p><div class="cohort-split"><div><strong>Affected: '+sick.toFixed(0)+'</strong><p>× sensitivity '+(se*100).toFixed(0)+'%</p><p>↓ '+tp.toFixed(0)+' true positives</p><p>'+ (sick-tp).toFixed(0)+' false negatives</p></div><div><strong>Unaffected: '+well.toFixed(0)+'</strong><p>× false-positive rate '+((1-sp)*100).toFixed(1)+'%</p><p>↓ '+fp.toFixed(0)+' false positives</p><p>'+(well-fp).toFixed(0)+' true negatives</p></div></div><p>Now look only at the '+positive.toFixed(0)+' positive results:</p><div class="positive-bar" aria-label="'+(100*tp/positive).toFixed(1)+' percent true positives"><span style="width:'+100*tp/positive+'%"></span><span class="false" style="width:'+100*fp/positive+'%"></span></div><p>True: '+tp.toFixed(0)+' / '+positive.toFixed(0)+' = <strong>'+(100*tp/positive).toFixed(1)+'%</strong>. False: '+fp.toFixed(0)+'. Counts are rounded after calculation.</p><p>Lower prevalence enlarges the unaffected pool. A small false-positive rate applied to that large pool can outnumber true positives. Synthetic arithmetic, not medical advice or measured test performance.</p>';}
const syncMechanism=()=>{show();drawMechanism();};[prevalence,sensitivity,specificity].forEach(e=>e.oninput=syncMechanism);drawMechanism();
